import{_ as t,c as a,o as i,ae as n}from"./chunks/framework.Cd-3tpCq.js";const h=JSON.parse('{"title":"Delete Email Template","description":"","frontmatter":{"outline":false,"examples":[{"id":"delete","title":"Delete Email Template","description":"Delete an email template by id. A successful delete returns no errors; the template is removed.","query":"mutation DeleteAdminMarketingTemplate(\\n  $input: deleteAdminMarketingTemplateInput!\\n) {\\n  deleteAdminMarketingTemplate(input: $input) {\\n    adminMarketingTemplate {\\n      _id\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"id\\": \\"/api/admin/marketing/templates/21\\"\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"deleteAdminMarketingTemplate\\": {\\n      \\"adminMarketingTemplate\\": null\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/marketing/communications/templates-delete.md","filePath":"api/graphql-api/admin/marketing/communications/templates-delete.md"}'),l={name:"api/graphql-api/admin/marketing/communications/templates-delete.md"};function d(o,e,s,r,m,p){return i(),a("div",null,e[0]||(e[0]=[n('<h1 id="delete-email-template" tabindex="-1">Delete Email Template <a class="header-anchor" href="#delete-email-template" aria-label="Permalink to &quot;Delete Email Template&quot;">​</a></h1><p>Deletes an email template — the <strong>Delete</strong> row action on the admin <strong>Marketing → Communications → Email Templates</strong> screen.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>New here? Read the <a href="/api/graphql-api/admin/marketing/communications/templates/">Email Templates overview</a> for what an email template does and how its fields behave.</p></div><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>deleteAdminMarketingTemplate</code></td><td>Mutation</td><td>Delete an email template</td></tr></tbody></table><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Requires an admin Bearer token and the <code>marketing.communications.email_templates.delete</code> permission.</li><li>Pass the template&#39;s IRI as <code>id</code>. Use the <a href="/api/graphql-api/admin/marketing/communications/templates-list.html">list</a> query to discover valid ids.</li></ul><div class="warning custom-block"><p class="custom-block-title">Confirm success via the absence of <code>errors</code></p><p>The delete mutation returns a success acknowledgement, not the deleted template&#39;s data — <code>adminMarketingTemplate</code> resolves to <code>null</code> on the payload. <strong>Treat a response with no <code>errors[]</code> as a successful delete.</strong> If you need a confirmation message in the body, use the REST endpoint (<code>DELETE /api/admin/marketing/templates/{id}</code>), which returns <code>{ &quot;message&quot;: &quot;Email template deleted.&quot; }</code>.</p></div><h2 id="input-fields" tabindex="-1">Input fields <a class="header-anchor" href="#input-fields" aria-label="Permalink to &quot;Input fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>id</code></td><td>ID</td><td>Yes</td><td>The template&#39;s IRI</td></tr></tbody></table>',10)]))}const u=t(l,[["render",d]]);export{h as __pageData,u as default};
